"use client"

import { useState, useEffect } from "react"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Button } from "@/components/ui/button"
import { Student } from "@/services/student.service"
import SchoolSelect from "@/components/dropdown/dropdown"
import { useStudentStore } from "@/store/student.store"

interface StudentFormProps {
  initialData?: Student | null
  title: string
  onSubmit: (data: FormData) => Promise<void>
}

const defaultStudent: Student = {
  IDNo: "",
  AdmissionNo: "",
  NameOfThePupil: "",
  StudentAadhaarNo: "",
  PENNo: "",
  AAPARID: "",
  FatherName: "",
  FatherAadhaarNo: "",
  FatherMobileNumber: "",
  ParentOccupation: "",
  MotherName: "",
  MotherAadharNo: "",
  MotherMobileNo: "",
  MotherBankAccountNo: "",
  MailID: "",
  ResidenceAddress: "",
  BankIFSCCode: "",
  PreviousSchoolClass: "",
  ClassAdmitted: "",
  ClassLeaving: "",
  TCNumber: "",
  LeavingTCNo: "",
  TCTakenDate: "",
  DateOfAdmission: "",
  DateOfBirth: "",
  DateOfLeaving: "",
  Nationality: "Indian",
  Religion: "",
  Caste: "",
  SubCaste: "",
  MotherTongue: "",
  PhotoOfStudent: "",
  EntryDate: "",
  SchoolName: "",
  AcademicYear: "",
}

export default function StudentForm({
  initialData,
  title,
  onSubmit,
}: StudentFormProps) {
  const [formData, setFormData] = useState<Student>(defaultStudent)
  const { school: selectedSchool, setSchool } = useStudentStore()

  useEffect(() => {
    if (initialData) {
      setFormData({ ...defaultStudent, ...initialData })
      if (initialData.SchoolName) setSchool(initialData.SchoolName)
    }
  }, [initialData, setSchool])

  const handleChange = (key: keyof Student, value: any) => {
    setFormData((prev) => ({ ...prev, [key]: value }))
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    const payload = new FormData()
    Object.entries(formData).forEach(([key, value]) => {
      if (key === "PhotoOfStudent") {
        if (value instanceof File) payload.append(key, value)
      } else if (value !== null && value !== undefined) {
        payload.append(key, String(value))
      }
    })

    if (selectedSchool) payload.append("SchoolName", selectedSchool)

    await onSubmit(payload)
  }

  return (
    <div className="max-w-6xl mx-auto p-6 space-y-6">
      <h1 className="text-2xl font-bold">{title}</h1>

      <form onSubmit={handleSubmit} className="space-y-8">

        {/* STUDENT DETAILS */}
        <section className="border rounded-lg p-4">
          <h2 className="font-semibold mb-4">Student Details</h2>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <Label>School</Label>
              <SchoolSelect value={selectedSchool} onChange={setSchool} />
            </div>

            {Object.entries(formData).map(([key, value]) => {
              if (
                key === "id" ||
                key === "EntryDate" ||
                key === "SchoolName" ||
                key.startsWith("Father") ||
                key.startsWith("Mother")
              )
                return null

              return (
                <div key={key}>
                  <Label>{key.replace(/([A-Z])/g, " $1")}</Label>
                  {key === "PhotoOfStudent" ? (
                    <Input
                      type="file"
                      accept="image/*"
                      onChange={(e) =>
                        handleChange(key as keyof Student, e.target.files?.[0])
                      }
                    />
                  ) : (
                    <Input
                      value={value || ""}
                      onChange={(e) =>
                        handleChange(key as keyof Student, e.target.value)
                      }
                    />
                  )}
                </div>
              )
            })}
          </div>
        </section>

        {/* FATHER DETAILS */}
        <section className="border rounded-lg p-4">
          <h2 className="font-semibold mb-4">Father Details</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {["FatherName", "FatherAadhaarNo", "FatherMobileNumber", "ParentOccupation"].map(
              (key) => (
                <div key={key}>
                  <Label>{key.replace(/([A-Z])/g, " $1")}</Label>
                  <Input
                    value={(formData as any)[key] || ""}
                    onChange={(e) =>
                      handleChange(key as keyof Student, e.target.value)
                    }
                  />
                </div>
              )
            )}
          </div>
        </section>

        {/* MOTHER DETAILS */}
        <section className="border rounded-lg p-4">
          <h2 className="font-semibold mb-4">Mother Details</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {["MotherName", "MotherAadharNo", "MotherMobileNo", "MotherBankAccountNo"].map(
              (key) => (
                <div key={key}>
                  <Label>{key.replace(/([A-Z])/g, " $1")}</Label>
                  <Input
                    value={(formData as any)[key] || ""}
                    onChange={(e) =>
                      handleChange(key as keyof Student, e.target.value)
                    }
                  />
                </div>
              )
            )}
          </div>
        </section>

        <div className="flex justify-end gap-3">
          <Button variant="outline" type="button">
            Cancel
          </Button>
          <Button type="submit">{title}</Button>
        </div>
      </form>
    </div>
  )
}
